import type { Column, Typed } from '../Column'
import type { Record } from '../Record'
import type { TableName } from '..'
import type { choiceDropdownType, Choices } from './Choice'

// TODO: Record<RefTable>[]  does not work with now-sdk, leaving it here to support flow's usecases
type ListColumnType<
    RefTable extends TableName = TableName,
    TChoices extends Choices<string> = Choices<string>,
    Dropdown extends choiceDropdownType = choiceDropdownType,
    Type extends Record<RefTable>[] | string[] | string = Record<RefTable>[] | string[] | string,
    Default extends Type = Type,
> = Column<Type, Default> & {
    /** Table containing possible values for this list (for reference-based lists) */
    referenceTable?: RefTable
    /** Choice values definitions as object literal: { choice_1: { label: 'Choice1' }, choice_2: { label: 'Choice2' } } */
    choices?: TChoices
    /** How a list of choices displays for users of your form */
    dropdown?: Dropdown | choiceDropdownType
}

/**
 * A Column for a list type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 *   * **referenceTable**? - table containing possible values for this list
 *   * **choices**? - choice value definitions for string-based lists
 *   * **dropdown**? - how a list of choices displays for users of your form
 */
export function ListColumn<
    const RefTable extends TableName,
    const TChoices extends Choices<string>,
    const Dropdown extends choiceDropdownType,
    const Type extends Record<RefTable>[] | string[] | string,
    const Default extends Type,
    const C extends ListColumnType<RefTable, TChoices, Dropdown, Type, Default>,
>(config: C & ListColumnType<RefTable, TChoices, Dropdown, Type, Default>) {
    return config as Typed<Type, C>
}
